-- Migration: 10 example articles for AI reference (v2 — fixed "gue" → "aku")
INSERT INTO app_settings (key, value) VALUES ('content_examples', $$ {
  "mind-body": {
    "title": "Kenapa Otak Kita Nggak Bisa Berhenti Mikir Pas Lagi Mau Tidur — dan Ini Bukan Salahmu",
    "content": "<p>Coba inget kapan terakhir kali kamu beneran tidur dengan kepala kosong. Bukan tidur karena capek banget sampai pingsan. Tapi tidur yang damai — di mana kamu merebahkan diri, memejamkan mata, dan hening. Susah diingat, kan?</p><p>Aku inget banget masa-masa itu. Semester 5, jam 11 malam, badan udah di kasur, lampu udah mati, tapi kepalaku malah kayak ruang rapat dadakan. Semua topik dibahas: kenapa tadi aku ngomong begitu ke temen? Deadline minggu depan udah siap belum? Dan yang paling favorit: kesalahanku tahun 2017 yang tiba-tiba muncul lagi tanpa diundang.</p><h2>Yang Sebenarnya Terjadi di Kepalamu Secara Biologis</h2><p>Otak kamu punya dua mode operasi utama. Mode pertama adalah task-positive network — ini yang aktif pas kamu lagi fokus ngerjain sesuatu. Mode kedua adalah default mode network (DMN) — ini yang aktif pas kamu nggak ngapa-ngapain. DMN ini kayak layanan kebersihan otak. Dia aktif pas kamu lagi kosong, termasuk berbaring di kasur menunggu tidur. Masalahnya: DMN tidak bisa membedakan antara masalah serius dan pikiran random. Jadi semua dilempar ke layar — kayak notifikasi HP yang numpuk.</p><blockquote>Kamu bukan anomali. Kamu mayoritas.</blockquote><p>Kalau malam ini masih susah, gak apa-apa. Besok kita coba lagi.</p>"
  },
  "beauty-skincare": {
    "title": "Review Jujur: 5 Sunscreen Lokal yang Aku Coba Sendiri Seharian — Mana yang Worth It?",
    "content": "<p>Okay jadi aku akan jujur dari awal: aku bukan beauty influencer. Aku cuma cewek yang kulitnya gampang jerawatan, gampang kusam, dan trauma sama sunscreen yang bikin whitecast kayak hantu. Tapi karena semua orang (termasuk dokter kulit yang aku follow) terus bilang sunscreen itu wajib, aku akhirnya memutuskan buat nyobain 5 sunscreen lokal yang paling sering direkomendasikan.</p><h2>Kenapa Sunscreen?</h2><p>Singkatnya: UV itu jahat. Dia bikin kulit kusam, flek hitam, dan penuaan dini. Dan sunscreen adalah tamengnya. Tapi nemu sunscreen yang cocok itu kayak nyari jodoh — banyak yang gagal sebelum nemu yang pas.</p><h2>Review Satu per Satu</h2><p>Aku cobain masing-masing 2-3 hari, pakai setelah moisturizer, sebelum makeup (kalau lagi pakai). Ini hasilnya.</p><p>Yang paling worth it? Sunscreen nomor 3. Ringan, gak bikin whitecast, dan harganya cukup bersahabat buat kantong pelajar.</p><blockquote>Kulit kamu unik. Yang cocok buat influencer belum tentu cocok buat kamu. Jadi pake ini sebagai referensi, bukan aturan mutlak.</blockquote>"
  },
  "wellness": {
    "title": "Kenapa Kamu Selalu Lelah Meski Udah Tidur 8 Jam — dan Ini Bukan Cuma Soal Kopi",
    "content": "<p>Aku pernah di fase di mana aku tidur 8 jam, bangun, dan… tetap capek. Bukan capek biasa. Capek yang aneh — badan udah di kampus, tapi jiwa masih di kasur. Dan pertanyaan pertama yang selalu muncul: Apa aku kurang tidur? Apa aku perlu tidur lebih lama? Atau jangan-jangan aku cuma males?</p><p>Ternyata jawabannya bukan tidur lebih lama. Ada beberapa hal yang bikin kita tetap lelah meski jam tidur udah cukup — dan kebanyakan orang gak nyangka.</p><h2>1. Kualitas Tidur > Kuantitas Tidur</h2><p>Kamu bisa tidur 10 jam tapi kalau tidurmu terfragmentasi (sering kebangun, banyak mimpi buruk, gelisah), tubuhmu gak masuk ke deep sleep yang sebenarnya dibutuhkan buat pemulihan.</p><h2>2. Zat Besi — Si Biang Keladi yang Sering Gak Ketahuan</h2><p>Data dari Journal of Nutrition (2021) menunjukkan bahwa 1 dari 3 perempuan usia 15-24 tahun di Asia Tenggara mengalami defisiensi zat besi. Gejalanya? Capek terus, susah fokus, mood gak stabil — persis kayak burnout. Tapi jarang yang ngecek.</p><blockquote>Kamu bukan malas. Mungkin tubuhmu cuma butuh sesuatu yang belum kamu kasih.</blockquote>"
  },
  "style-shopping": {
    "title": "Haul Shopee Baju Kondangan Budget 150 Ribu — Worth It atau Nggak?",
    "content": "<p>Aku punya undangan nikah sepupu bulan depan. Budget baju? 150 ribu. Termasuk ongkir. Mission impossible? Ternyata enggak.</p><p>Aku scrolling Shopee selama 3 hari buat nemu 3 baju kondangan yang masuk budget. Ini hasilnya — jujur, tanpa filter.</p><h2>Baju 1: Dress Satin Rp 65.000</h2><p>Ekspektasi: kayak di foto. Realita: bahannya lebih tipis dari yang aku kira. Tapi setelah dipake dan di-style dengan belt tambahan, lumayan lah buat kondangan siang. Jauh-jauh dikit, lighting bagus — bisa lewat.</p><h2>Baju 2: Kebaya Modern Rp 85.000</h2><p>Ini yang paling worth it. Jahitan rapi, warna sesuai foto, dan yang paling penting: gak bikin gatal. Buat kondangan malam, ini juara.</p><blockquote>Kadang yang murah bukan berarti murahan. Tapi emang perlu effort lebih buat nemunya.</blockquote>"
  },
  "entertainment": {
    "title": "5 Drakor yang Aku Rekomendasikan Kalau Kamu Lagi Butuh Nangis Tanpa Sebab",
    "content": "<p>Ada tipe drakor yang kamu tonton buat hiburan. Ada yang buat deg-degan. Dan ada satu kategori spesifik yang aku sebut terapi nangis murah — drakor yang bikin kamu nangis tanpa alasan jelas, dan setelahnya kamu ngerasa lebih ringan.</p><p>Ini 5 drakor yang aku rekomendasikan buat sesi terapi mandiri kamu.</p><h2>1. Move to Heaven (2021)</h2><p>Ini bukan drakor romance. Ini tentang seorang pemuda dengan Asperger yang bekerja sebagai trauma cleaner — membersihkan barang-barang orang yang sudah meninggal. Setiap episode adalah satu cerita tentang kehilangan, penyesalan, dan kata-kata yang gak sempat terucap.</p><h2>2. Our Blues (2022)</h2><p>Ensemble cast, semua karakter punya luka masing-masing. Yang bikin spesial: gak ada karakter yang jahat. Semua orang cuma manusia yang berusaha sebaik mungkin dengan apa yang mereka punya.</p><blockquote>Kadang nangis itu bukan karena sedih. Tapi karena akhirnya ada yang ngertiin.</blockquote>"
  },
  "lifetainment": {
    "title": "5 Makanan di Drakor yang Bikin Ngiler — dan Ternyata Ada Versi Murahnya di Indonesia",
    "content": "<p>Pernah nggak lagi nonton drakor, terus karakter utamanya buka tutup panci dan keluarlah semangkuk ramyeon yang kelihatannya enak banget sampai kamu pause dulu, buka GoFood, terus bingung mau order apa karena nggak ada yang kayak gitu? Ini bukan cuma kamu.</p><h2>Ramyeon — Si Mie Instan yang Terasa Gourmet di Drakor</h2><p>Di dunia nyata: mie instan 3 menit. Di drakor: makanan yang dimakan tengah malam setelah menangis atau merayakan sesuatu yang kecil. Kenapa kelihatan beda? Karena disajikan di panci langsung, dengan telur setengah matang dan sumpit metal.</p><p>Versi Indonesia: Shin Ramyun udah ada di minimarket, 8-12 ribu. Masak di panci kecil, tambah telur + daun bawang + keju slice. Makan langsung dari pancinya. Trust me.</p><h2>Tteokbokki</h2><p>Kue beras kenyal dalam saus pedas-manis. Versi paling accessible: Yopokki instan, 25-35 ribu di marketplace.</p><blockquote>Setengah dari vibe drakor itu makanannya, setengah lagi dengan siapa kamu makannya. Makan ramyeon sendirian di kamar jam 11 malam sambil nonton drakor itu valid.</blockquote>"
  },
  "relationship": {
    "title": "Anatomy of a Toxic Friendship: Kenapa Kita Sering Tau Tapi Nggak Bisa Pergi",
    "content": "<p>Kita banyak banget ngomongin toxic relationship. Tapi jarang yang ngomongin toxic friendship. Padahal teman yang toxic itu lebih susah dikenali — karena gak ada label putus dalam pertemanan. Kamu cuma… berharap dia berubah. Atau berharap kamu yang jadi lebih kuat.</p><h2>Ciri-ciri yang Sering Kita Abaikan</h2><p>Teman yang cuma muncul pas butuh sesuatu. Yang selalu bikin kamu ngerasa kecil setelah ngobrol. Yang ngomongin kamu di belakang tapi manis di depan. Yang bikin kamu ngerasa bersalah karena punya batasan.</p><p>Dan yang paling jahat: yang bikin kamu mempertanyakan apakah kamu terlalu sensitif atau berlebihan.</p><h2>Kenapa Susah Pergi</h2><p>Karena kita punya sejarah. Karena dia pernah jadi orang yang penting. Karena kita takut sendirian. Karena kita berharap suatu hari dia akan balik jadi versi dirinya yang dulu.</p><blockquote>Meninggalkan bukan berarti kamu gagal. Kadang itu adalah bentuk paling dewasa dari mencintai diri sendiri.</blockquote>"
  },
  "levelup-career": {
    "title": "Side Hustle yang Realistis Dimulai Pas Masih Kuliah — Tanpa Harus Jago Dulu",
    "content": "<p>Aku benci artikel yang judulnya 10 Side Hustle untuk Mahasiswa tapi isinya: jadi freelancer (perlu skill), jadi dropshipper (perlu modal), atau jadi content creator (perlu follower). Kayak, maaf ya, tapi kalau aku udah punya semua itu, aku gak akan baca artikel ini.</p><p>Jadi aku bikin versi yang lebih jujur. Side hustle yang bisa dimulai dengan skill yang kamu punya SEKARANG.</p><h2>1. Jasa ketik / transkrip</h2><p>Bosen? Iya. Tapi ini entry point paling rendah. Banyak dosen atau peneliti yang butuh transkrip wawancara. Kamu cuma perlu bisa ngetik cepat dan teliti. Rate: 50-100 ribu per jam audio.</p><h2>2. Jualan template Canva/Notion</h2><p>Kamu gak perlu jadi desainer. Bikin template sederhana — planner mingguan, tracker habit, CV aesthetic — jual di marketplace kreatif. Satu template bisa dijual berkali-kali.</p><blockquote>Kamu gak perlu jago dulu buat mulai. Tapi kamu perlu mulai buat jadi jago.</blockquote>"
  },
  "creative-space": {
    "title": "Journaling Bukan Buat yang Hidupnya Aesthetic — Panduan Jujur untuk Pemula",
    "content": "<p>Aku dulu benci journaling. Bukan karena gak suka nulis, tapi karena semua contoh yang aku lihat di internet tuh kayak: bullet journal yang rapi banget, tulisan tangan yang indah, sticker dan washi tape di mana-mana. Aku cuma punya pulpen butut dan tulisan dokter.</p><p>Ternyata journaling bukan itu. Journaling adalah ngobrol sama diri sendiri. Tanpa filter. Tanpa estetika.</p><h2>Metode Paling Sederhana: Brain Dump</h2><p>Buka notes HP atau buku tulis. Tulis apa aja yang ada di kepala. Gak diedit. Gak difilter. Kayak membuang sampah mental ke tempat sampah. Selesai. Gak perlu cantik.</p><h2>Metode Favorit: Satu Kalimat Sehari</h2><p>Gak perlu paragraf. Cuma satu kalimat. Misalnya: Hari ini aku sedih dan aku gak tau kenapa. Atau: Hari ini kopiku enak. Yang penting jujur.</p><blockquote>Journaling bukan buat orang yang hidupnya aesthetic. Journaling buat orang yang pengen ngerti dirinya sendiri.</blockquote>"
  },
  "tech-gaming": {
    "title": "Cara Pakai AI untuk Skripsi Tanpa Kena Tuduhan Plagiarisme — Panduan Etis",
    "content": "<p>Aku akan ngomong jujur dari awal: AI itu tools. Bukan jalan pintas. Dan kalau kamu pake AI buat nulis skripsi dari awal sampai akhir tanpa mikir, kamu gak cuma curang — kamu juga gak belajar apa-apa.</p><p>Tapi AI bisa jadi asisten riset yang luar biasa. Ini cara pakenya yang etis, aman, dan gak bikin kamu kena sidang etik.</p><h2>1. Brainstorming, Bukan Copy-Paste</h2><p>AI bagus buat ngehasilin ide. Tolong kasih 5 sudut pandang berbeda tentang topik X. Tapi jangan copy-paste hasilnya. Baca, pahami, tulis ulang dengan bahasamu sendiri.</p><blockquote>AI itu kayak kalkulator. Dia bantu kamu itung lebih cepat, tapi kamu tetap harus ngerti matematikanya.</blockquote>"
  },
  "opinion": {
    "title": "Kenapa Kuliah di Indonesia Terasa Seperti Survival Game — dan Ini Bukan Salah Mahasiswanya",
    "content": "<p>Ada momen di semester 5 di mana aku duduk di perpustakaan kampus jam 10 malam, menatap layar laptop yang menampilkan 3 deadline berbeda, dan bertanya-tanya: kenapa sistem pendidikan kita terasa seperti dirancang untuk membuat mahasiswanya kelelahan, bukan untuk belajar?</p><p>Ini bukan curhatan. Ini adalah pertanyaan serius yang perlu kita tanyakan bersama.</p><h2>UKT Naik, Fasilitas Jalan di Tempat</h2><p>Data dari Kemendikbud menunjukkan bahwa rata-rata UKT naik 15-30% dalam 3 tahun terakhir. Sementara itu, fasilitas dasar seperti akses jurnal internasional, ruang diskusi, dan layanan kesehatan mental kampus — masih jadi barang mewah di banyak kampus.</p><h2>Mental Health Bukan Cuma Tanggung Jawab Mahasiswa</h2><p>Kita sering denger narasi 'mahasiswa harus resilient.' Tapi resilience tanpa support system itu seperti diminta berenang tanpa air. Kampus perlu lebih dari sekadar poster 'Jaga Kesehatan Mental' di mading.</p><blockquote>Mengkritik bukan berarti tidak bersyukur. Justru karena kita peduli, kita berani bicara.</blockquote>"
  },
  "news": {
    "title": "Ribuan Kuota Beasiswa KIP Kuliah 2026 Resmi Dibuka — Ini Syarat dan Cara Daftarnya",
    "content": "<p>Kabar baik buat kamu yang lagi persiapan kuliah! Kementerian Pendidikan resmi membuka pendaftaran KIP Kuliah untuk tahun ajaran 2026 dengan kuota lebih dari 200.000 mahasiswa baru.</p><h2>Siapa yang Bisa Mendaftar?</h2><p>Siswa SMA/SMK/sederajat yang akan lulus tahun ini dan berasal dari keluarga kurang mampu secara ekonomi. Prioritas diberikan kepada pemegang Kartu Indonesia Pintar (KIP) dan yang terdaftar di Data Terpadu Kesejahteraan Sosial (DTKS).</p><h2>Cara Mendaftar</h2><p>Pendaftaran dilakukan secara online melalui portal resmi KIP Kuliah. Siapkan dokumen seperti kartu keluarga, rapor, dan surat keterangan tidak mampu. Deadline pendaftaran: 31 Agustus 2026.</p><blockquote>Pendidikan itu hak, bukan privilege. Jangan ragu buat daftar.</blockquote>"
  }
} $$)
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
